import java.util.*;

public class Solution {
    public long numTriplets(int[] nums1, int[] nums2) {
        Map<Integer, Integer> m1 = new HashMap<>();
        Map<Integer, Integer> m2 = new HashMap<>();
        for (int x : nums1) m1.put(x, m1.getOrDefault(x, 0) + 1);
        for (int x : nums2) m2.put(x, m2.getOrDefault(x, 0) + 1);
        return countType(m1, m2) + countType(m2, m1);
    }

    private long countType(Map<Integer, Integer> squareMap, Map<Integer, Integer> pairMap) {
        long res = 0;
        // For each value in squareMap, its square should equal product of two numbers from pairMap
        for (Map.Entry<Integer, Integer> e : squareMap.entrySet()) {
            long val = e.getKey();
            long square = val * val;
            long pairCount = 0;
            // Iterate over keys in pairMap and count unordered pairs (b, c) with b * c == square
            for (Map.Entry<Integer, Integer> eb : pairMap.entrySet()) {
                int b = eb.getKey();
                if (b == 0) continue; // values >=1 by constraints, but safe guard
                if (square % b != 0) continue;
                long cLong = square / b;
                if (cLong < b) continue; // ensure we count each unordered pair once
                if (cLong > Integer.MAX_VALUE) continue;
                Integer freqC = pairMap.get((int)cLong);
                if (freqC == null) continue;
                int freqB = eb.getValue();
                if (b == cLong) {
                    pairCount += (long) freqB * (freqB - 1) / 2;
                } else {
                    pairCount += (long) freqB * freqC;
                }
            }
            res += (long) e.getValue() * pairCount;
        }
        return res;
    }
}

